const M = mut({
  off_x: 0,
  off_y: -10,
  off_z: -.1,
})

document.M = M


const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera( 75, window.innerWidth / window.innerHeight, 0.1, 1000 );
const orbit = addons.OrbitControls
const loader = new THREE.TextureLoader()

let structure = undefined

const renderer = new THREE.WebGLRenderer();
renderer.setSize( window.innerWidth, window.innerHeight );
document.body.appendChild( renderer.domElement );

function apply_offset(){
      console.log("Applying to stu", structure)
  if (structure){
    Object.values(structure).forEach((cateogry, c_index) => {
      console.log("Applying", cateogry)
      if (!cateogry) return
      cateogry.forEach((el, e_index) => {
        if (!el || !el.position) return
        el.position.x = e_index * M.off_x
        el.position.y = c_index * M.off_y
        el.position.z = e_index * M.off_z
      })
    })
  }
}

eff_on(() => M.off_x, apply_offset )
eff_on(() => M.off_z, apply_offset )
eff_on(() => M.off_y, apply_offset )


