async function fetch_category(dir){
  return await fetch(dir)
    .then((res) => res.json())
    .then((res) => {
      return {
        title: `gaming-${parseInt(Math.random() * 50)}`,
        files: res.files.map(file => dir+file)
      }
    })
}


    //structure = init_structure([category])

/**
@typedef {Object} category 
@property {string} category.title
@property {Array<string>} category.files

@param {Array<category>} categories 
*/
function init_structure(categories) {
  let struct = {}

  categories.forEach((category, c_index) => {
    let elements = category.files.map((file, e_index) => {
      let element = {
        // based on c_index and e_index
        position: {
          x: e_index * .1, 
          y: 0,
          z: e_index* -.1,
        },

        // to attach to
        three: undefined,

        // update fn
        tick: function(){
          if (this.three){
            // check three positon with this position
            // if not eq, update three position
            if (!eq(this.three.position, this.position)){
              this.three.position.x = this.position.x
              this.three.position.y = this.position.y
              this.three.position.z = this.position.z
            }
          }

        }
      }
      create_image_plane(file, element)

      return element
    })
    struct[category.title] = elements
  })

  console.log(struct)
  return struct


  // will accept categories (dir) and textures (files)
  // will make a data structure
  // based on data strucutre spawn planes for image
  // plane maker will attach itself to ref we pass
  // to elem instance or whatever

  // data structure of each element will have a tick fn
  // every update cycle this is called

}


function create_image_plane(image, element){
  loader.load(image, function(texture){
    let w = texture.source.data.naturalWidth
    let h = texture.source.data.naturalHeight

    let aspect = w/h
    let aw = 5
    let ah = aw / aspect 

    const geometry = new THREE.PlaneGeometry(aw, ah);

    const material = new THREE.MeshBasicMaterial({ 
        map: texture,
        opacity: .5,
        transparent: true
    });


    // Create mesh
    const plane = new THREE.Mesh(geometry, material);

    // Scale the plane to match image dimensions
    const scale = new THREE.Vector3();
    texture.image.addEventListener('load', () => {
        scale.set(texture.image.width, texture.image.height, 1);
        plane.scale.copy(scale);
    });

    scene.add(plane)
    element.three = plane
  });
}

