function custom_renderer(state, i, c) {
  const code = mem(() => state?.renderer 
    ? state?.renderer 
    :  custom_renderer.toString())

  const id = uid();
  const output = sig("")
  let save, focus, focus_on_pos;

  const output_component = () => {

    let parent = `
      position: relative;
      width: 400px;
      height: 400px;
      background: white;
    `

    let one_coords = mut({ x: 0, y: 0 })
    let two_coords = mut({ x: 0, y: 0 })
    defer(() => { eff_on(() => one_coords.x,
           () => m().off_x = one_coords.x / 200 )

    eff_on(() => one_coords.y,
           () => m().off_z = (one_coords.y / 200) * -1 )

 }, 500);    setTimeout(() => one_coords.x = -.2, 3000)

    let wi = 50, he=50

    let one = mem(() => `
      position: absolute;
      top: ${one_coords.y}px;
      left: ${one_coords.x}px;
      width: ${wi}px;
      height: ${he}px;
      background: black;
    `)

    let one_ref = (e) => {
      const set_left = (x) => one_coords.x = x
      const set_top = (y) => one_coords.y = y
      setTimeout(() => drag(e,  {set_left, set_top} ), 200) 
    }

    // 1 parent
    // 2 divs
    // x distance between divs = x offset

    return h("div", {style: parent}, 
             h("div", {style: one, ref: one_ref}))
  }

  const render = () => {
    mounted(() => {
      const cm_editor = make_code_mirror(code(), id, []);
      focus = () => setTimeout(() => cm_editor.focus(), 100);

      save = function(el) {
        const text = cm_editor.state.doc.toString() 
        el.output = output()
        el.focused = cm_editor.hasFocus;
        el.renderer = text;
        el.cursor = cm_editor.state.selection.ranges[0].from;
      };

      defer(function() {
        if (state.cursor && state.focused) {
          const selection = { anchor: state.cursor, head: state.cursor };
          cm_editor.focus();
          cm_editor.dispatch({ selection });
        }
      });
    });
    return  h("div", 
              h("div", output_component),
              h("div", { class: "editor-" + id }))
  };

  return ({
      render: render,
      onfocus: () => focus(),
      write: (...args) => save(...args),
  });
}
